2509:   drawPlant(px, py, slot, strain, p, index) {
2510:     const ctx = this.ctx;
2511:     if (!strain) return;
2512:     const prog = slot.progress;
2513:     const sway = Math.sin(this.time * 1.3 + index * 1.7) * .035;
2514:     const scale = .55 + prog * .55;
2515:     const stemH = 26 + prog * 40;
2516:     ctx.save();
2517:     ctx.translate(px, py - 2);
2518:     // stem
2519:     const topX = Math.sin(sway * 4) * 7, topY = -stemH;
2520:     ctx.strokeStyle = '#3f6e3f'; ctx.lineWidth = 2.1;
2521:     ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(2, -stemH * .55, topX, topY); ctx.stroke();
2522:     const nodes = prog < .35 ? 1 : prog < .7 ? 3 : 4;
2523:     for (let n = 0; n < nodes; n++) {
2524:       const t = (n + 1) / (nodes + .4);
2525:       const nx = topX * t * .7, ny = topY * t;
2526:       const dir = n % 2 ? 1 : -1;
2527:       const leafLen = (12 + prog * 12) * (1 - t * .25);
2528:       const ang = dir * (.7 + t * .2) + sway;
2529:       // stem branch
2530:       ctx.strokeStyle = '#4b7c48'; ctx.lineWidth = 1.4;
2531:       ctx.beginPath(); ctx.moveTo(nx, ny); ctx.quadraticCurveTo(nx + dir * leafLen * .5, ny - 4, nx + dir * leafLen, ny - 2); ctx.stroke();
2532:       // fan leaf shape
2533:       ctx.save(); ctx.translate(nx + dir * leafLen, ny - 2); ctx.rotate(ang);
2534:       ctx.fillStyle = n % 2 ? '#4f8a4a' : '#3f7340';
2535:       ctx.beginPath();
2536:       ctx.moveTo(0, 0);
2537:       ctx.bezierCurveTo(-6, -7, -15, -4, -18, 0);
2538:       ctx.bezierCurveTo(-13, 5, -5, 6, 0, 0);
