const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  page.on('pageerror', err => console.error('PAGE ERROR:', err.message));
  page.on('console', msg => { if (msg.type() === 'error') console.error('CONSOLE ERROR:', msg.text()); });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.locator('#btnStart').click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '/tmp/opencode/latest-scene.jpg', type: 'jpeg', quality: 90 });
  console.log('Captured', await page.locator('#scene').evaluate(c => `${c.width}x${c.height}`));
  console.log('Debug available:', await page.evaluate(() => !!window.__GREEN_EMPIRE__));
  await browser.close();
})();

